INSERT INTO `conversation` (`id`, `user_id`, `title`, `risk_level`, `turn_count`, `status`, `create_time`, `update_time`) VALUES
  (1, 6, '秋招投了六十多份简历，面试只有三次，感觉', 'LOW', 3, 0, '2026-09-11 15:14:13', '2026-09-11 17:42:29'),
  (2, 6, '父母感情不好，每次放假回家都要处理他们的', 'LOW', 3, 1, '2026-08-13 17:25:13', '2026-08-13 20:38:24'),
  (3, 6, '快到期末考试了，四门专业课堆在一起，感觉', 'LOW', 2, 1, '2026-09-17 09:09:13', '2026-09-17 11:10:35'),
  (4, 6, '舍友睡得晚，灯一直亮着，我又不好意思说，', 'LOW', 2, 0, '2026-09-13 15:55:13', '2026-09-13 18:07:20'),
  (5, 7, '感觉自己在这段关系里一直在退让，越来越不', 'MEDIUM', 2, 1, '2026-08-21 21:03:13', '2026-08-21 22:03:22'),
  (6, 7, '喜欢一个人很久了，但对方好像完全没感觉，', 'MEDIUM', 5, 1, '2026-08-06 15:16:13', '2026-08-06 17:54:31'),
  (7, 7, '有时候会突然很难过，在教室都想哭', 'MEDIUM', 4, 0, '2026-08-17 10:17:13', '2026-08-17 13:01:21'),
  (8, 7, '躺下之后脑子就开始不停地想事情，越想越清', 'MEDIUM', 3, 0, '2026-09-10 13:44:13', '2026-09-10 17:35:24'),
  (9, 7, '秋招投了六十多份简历，面试只有三次，感觉', 'HIGH', 4, 1, '2026-09-11 20:52:13', '2026-09-12 00:24:33'),
  (10, 7, '家里经济压力大，我不敢跟他们说我在学校也', 'HIGH', 2, 0, '2026-07-20 14:31:13', '2026-07-20 16:25:18'),
  (11, 8, '我性格比较内向，一到大场合就说不出话，事', 'LOW', 1, 0, '2026-06-29 10:37:13', '2026-06-29 11:03:21'),
  (12, 8, '小组作业基本都是我一个人在做，又怕说出口', 'LOW', 3, 1, '2026-08-21 22:43:13', '2026-08-21 23:48:17'),
  (13, 9, '明明知道不该这么想，但就是控制不住地否定', 'LOW', 1, 0, '2026-07-03 01:45:13', '2026-07-03 03:10:34'),
  (14, 9, '最近老是想着要是没有我，大家可能会轻松一', 'HIGH', 4, 1, '2026-07-12 22:05:13', '2026-07-13 01:33:22'),
  (15, 9, '异地恋坚持了一年多，最近他总是敷衍我，我', 'HIGH', 2, 0, '2026-09-09 00:37:13', '2026-09-09 02:17:25'),
