先做「物理隔离」：把聊天窗口折叠、必要的联系方式留一条就够。反复看记录会让恢复期拖长。

如果影响到了吃饭睡觉，我们再把节奏调一调。', 'PSYCH_EMOTION', 'LOW', 279, '2026-06-22 02:33:21'),
  (791, 135, 791, 'user', '实习的时候被领导当众批评，现在一想到上班就发怵', NULL, NULL, 0, '2026-06-22 03:01:13'),
  (792, 135, 792, 'assistant', '看到同学先有结果，会产生很强的比较压力，这很正常。

面试被拒往往和岗位匹配度有关，不完全是能力问题。可以记录每场面试被问住的问题，它们比简历更能指出该补什么。

这段时间先保证睡够，面试状态和睡眠直接相关。', 'PSYCH_EMOTION', 'LOW', 300, '2026-06-22 03:01:21'),
  (793, 136, 793, 'user', '考试焦虑有什么科学的缓解方法吗？', NULL, NULL, 0, '2026-06-24 21:24:13'),
  (794, 136, 794, 'assistant', '可以，先给你几条研究支持比较充分的做法。

放松训练里，渐进式肌肉放松和呼吸训练的证据最充分。每天十分钟，比偶尔做一次一小时更有效。

这些方法都适合自助，但如果两周没改善，建议找咨询师。', 'KNOWLEDGE_QUERY', 'LOW', 319, '2026-06-24 21:24:38'),
  (795, 136, 795, 'user', '作息完全乱了，早上起不来，晚上又睡不着，恶性循环', NULL, NULL, 0, '2026-06-24 21:47:13'),
  (796, 136, 796, 'assistant', '躺下之后脑子停不下来，这种情况比「睡不着」更消耗人。

下午三点以后不碰咖啡因，包括奶茶和可乐。很多人不知道奶茶的咖啡因含量其实不低。

你现在大概几点能躺下？我们从调整这个时间开始试试。', 'PSYCH_EMOTION', 'LOW', 191, '2026-06-24 21:47:19'),
  (797, 136, 797, 'user', '家里希望我考公务员，但我想做设计，一提就闹僵', NULL, NULL, 0, '2026-06-24 23:00:13'),
  (798, 136, 798, 'assistant', '「懂事」这个词有时候是负担，你已经背了很久了。

在校期间可以多利用学校的资源：导师、辅导员、心理咨询中心，把支持系统从家庭扩展到外部。

最近一次和家里通电话是什么时候？当时的感受还记得吗？', 'PSYCH_EMOTION', 'LOW', 235, '2026-06-24 23:00:28'),
  (799, 137, 799, 'user', '情绪一直很低，也说不上具体因为什么，就是开心不起来', NULL, NULL, 0, '2026-09-11 02:26:13'),
  (800, 137, 800, 'assistant', '持续的低落和兴趣减退，是值得认真对待的信号，不是「想开点」就能过去的。

低谷期不适合做重大决定，比如退学、分手、辞职。可以先把想法记下来，等状态回升再回头看。

这周有没有哪一刻稍微轻一点？哪怕很短。', 'PSYCH_EMOTION', 'MEDIUM', 186, '2026-09-11 02:26:29');

