  (813, 139, 813, 'user', '躺下之后脑子就开始不停地想事情，越想越清醒，特别痛苦', NULL, NULL, 0, '2026-06-23 22:22:13'),
  (814, 139, 814, 'assistant', '睡眠不好会连着影响情绪和注意力，你能注意到这件事本身很重要。

