  (821, 142, 821, 'user', '从小被要求「懂事」，现在好像连自己想要什么都不知道了', NULL, NULL, 0, '2026-07-11 05:00:13'),
  (822, 142, 822, 'assistant', '被反复比较是很难受的，尤其是来自最亲近的人。

和父母的沟通可以降低目标：不追求说服他们，只求把话说完。比如「我知道你们是为我好，但我想先按自己的想法试一年」。

先照顾好自己，这不是自私。', 'PSYCH_EMOTION', 'MEDIUM', 310, '2026-07-11 05:00:21'),
  (823, 142, 823, 'user', '不太想跟人说话，只想一个人待着', NULL, NULL, 0, '2026-07-11 05:58:13'),
  (824, 142, 824, 'assistant', '说不上原因的低落确实更难处理，因为它没有可以对着解决的靶子。

如果这种状态持续两周以上，并且影响到上课和人际，建议到校心理中心或医院精神科做一次评估，这是常规操作，不必有负担。

这种状态大概持续多久了？一个月还是更久？', 'PSYCH_EMOTION', 'LOW', 184, '2026-07-11 05:58:27'),
  (825, 142, 825, 'user', '这次高数考砸了，感觉自己根本不是学这个的料，一想到期末就更慌', NULL, NULL, 0, '2026-07-11 07:16:13'),
  (826, 142, 826, 'assistant', '你把这么多压力一次性说出来，我听着都觉得沉。

