压力大的时候，记得吃饭和睡觉是底线，别拿它们换复习时间。', 'PSYCH_EMOTION', 'MEDIUM', 301, '2026-07-11 07:16:21'),
  (827, 143, 827, 'user', '不知道自己适合做什么，专业也不喜欢，很迷茫', NULL, NULL, 0, '2026-07-23 22:44:13'),
  (828, 143, 828, 'assistant', '看到同学先有结果，会产生很强的比较压力，这很正常。

