目前手上有在推进的流程吗？我们可以一起看看卡在哪一环。', 'PSYCH_EMOTION', 'MEDIUM', 144, '2026-07-23 22:44:37'),
  (829, 144, 829, 'user', '每次考试前都会心慌手抖，明明复习过了还是控制不住地紧张', NULL, NULL, 0, '2026-07-15 02:05:13'),
  (830, 144, 830, 'assistant', '考试周把好几天的事情挤在一起，焦虑是很自然的反应。

