行为激活是改善低落情绪最直接的方法之一：不等有动力才行动，而是先安排小行动，动力往往跟着行为来。

这些方法都适合自助，但如果两周没改善，建议找咨询师。', 'KNOWLEDGE_QUERY', 'LOW', 295, '2026-09-04 19:46:22'),
  (971, 169, 971, 'user', '情绪低落的时候有什么自助的方法？', NULL, NULL, 0, '2026-08-22 17:40:13'),
  (972, 169, 972, 'assistant', '可以，先给你几条研究支持比较充分的做法。

认知行为疗法里的「想法记录」性价比很高：写下情境、自动冒出的念头、情绪强度，再写一条更贴近事实的替代想法。坚持两周通常能感到差别。

你想先从哪一条开始？', 'KNOWLEDGE_QUERY', 'LOW', 389, '2026-08-22 17:40:34'),
  (973, 169, 973, 'user', '考研倒计时不到两个月，做真题错一大半，晚上根本睡不着', NULL, NULL, 0, '2026-08-22 19:03:13'),
  (974, 169, 974, 'assistant', '先谢谢你愿意讲这些。你不是不够努力，是这段时间的负荷确实太大了。

可以试着把待办拆成「今天只做三件」的小块：一门课的一个章节 + 一套错题 + 一次复盘。完成感会明显一些，也不容易因为看到整座山而泄气。

这周你打算从哪一件小事开始？说说看，我陪你捋一遍。', 'PSYCH_EMOTION', 'LOW', 441, '2026-08-22 19:03:20'),
  (975, 170, 975, 'user', '情绪一直很低，也说不上具体因为什么，就是开心不起来', NULL, NULL, 0, '2026-08-25 09:32:13'),
  (976, 170, 976, 'assistant', '说不上原因的低落确实更难处理，因为它没有可以对着解决的靶子。

低谷期不适合做重大决定，比如退学、分手、辞职。可以先把想法记下来，等状态回升再回头看。

这种状态大概持续多久了？一个月还是更久？', 'PSYCH_EMOTION', 'LOW', 444, '2026-08-25 09:32:20'),
  (977, 171, 977, 'user', '爸妈总是拿我跟表姐比，每次打电话都要吵，现在都不敢接电话了', NULL, NULL, 0, '2026-07-13 16:36:13'),
  (978, 171, 978, 'assistant', '家里本该是能歇脚的地方，但有时候恰恰相反，这种落差很消耗人。

给家里打电话前设一个时长上限，比如先聊十分钟日常，超出部分不进入争论话题。把边界做出来，比硬扛有效。

先照顾好自己，这不是自私。', 'PSYCH_EMOTION', 'LOW', 332, '2026-07-13 16:36:18'),
  (979, 171, 979, 'user', '分手快一个月了，一直缓不过来，看到她的消息还是会心跳加速', NULL, NULL, 0, '2026-07-13 17:15:13'),
  (980, 171, 980, 'assistant', '感情里的消耗是慢性的，你能讲出来，说明已经在往外走了。

失恋的难受有生理基础，和戒断反应类似，通常几周后强度会自然下降。这段时间别用「我是不是太脆弱」来责备自己。

不用急着做决定，先把这周过稳。', 'PSYCH_EMOTION', 'LOW', 203, '2026-07-13 17:15:36'),
  (981, 171, 981, 'user', '感觉自己在这段关系里一直在退让，越来越不像自己了', NULL, NULL, 0, '2026-07-13 18:04:13'),
  (982, 171, 982, 'assistant', '一段关系结束后难受是正常的，不需要逼自己快点好起来。

把注意力放回具体的日常上：一顿饭、一次跑步、一次和朋友的见面。情绪没法靠想通解决，但可以靠生活重新填满。

如果影响到了吃饭睡觉，我们再把节奏调一调。', 'PSYCH_EMOTION', 'LOW', 370, '2026-07-13 18:04:38'),
  (983, 171, 983, 'user', '感觉撑不下去了，想结束这一切', NULL, NULL, 0, '2026-07-13 19:08:13'),
  (984, 171, 984, 'assistant', '听到你这么说，我很担心你。你愿意说出来，这需要很大的勇气，谢谢你信任我。

我想先确认一件事：**你现在是安全的吗？** 有没有正在做的、或者已经计划好的伤害自己的事？

请现在就联系能马上帮到你的人，不要一个人扛：
- **学校心理健康教育中心**（工作日可预约面谈）
- **全国24小时心理援助热线：400-161-9995**
- **北京心理危机研究与干预中心：010-82951332**
- 情况紧急时请直接拨打 **120** 或 **110**

你现在的痛苦是真实的，但它不等于永远。我这边也已经把这个情况同步给了学校心理中心的老师，他们会在了解情况后与你联系。在那之前，请尽量待在有人陪伴的地方。', 'RISK_ALERT', 'HIGH', 427, '2026-07-13 19:08:27'),
  (985, 171, 985, 'user', '身边的同学都拿到 offer 了，我还在等消息，每天都在自我怀疑', NULL, NULL, 0, '2026-07-13 19:14:13'),
  (986, 171, 986, 'assistant', '看到同学先有结果，会产生很强的比较压力，这很正常。

面试被拒往往和岗位匹配度有关，不完全是能力问题。可以记录每场面试被问住的问题，它们比简历更能指出该补什么。

目前手上有在推进的流程吗？我们可以一起看看卡在哪一环。', 'PSYCH_EMOTION', 'LOW', 318, '2026-07-13 19:14:36'),
  (987, 172, 987, 'user', '父母感情不好，每次放假回家都要处理他们的情绪，很累', NULL, NULL, 0, '2026-08-09 15:32:13'),
  (988, 172, 988, 'assistant', '家里本该是能歇脚的地方，但有时候恰恰相反，这种落差很消耗人。

在校期间可以多利用学校的资源：导师、辅导员、心理咨询中心，把支持系统从家庭扩展到外部。

最近一次和家里通电话是什么时候？当时的感受还记得吗？', 'PSYCH_EMOTION', 'LOW', 397, '2026-08-09 15:32:30'),
  (989, 172, 989, 'user', '分手快一个月了，一直缓不过来，看到她的消息还是会心跳加速', NULL, NULL, 0, '2026-08-09 16:39:13'),
  (990, 172, 990, 'assistant', '一段关系结束后难受是正常的，不需要逼自己快点好起来。

如果是「要不要继续」这类选择，可以写下继续和分开各自的代价，写下来往往比在心里翻来覆去清楚得多。

这一个月你都是怎么过的？有没有哪一天稍微好一点？', 'PSYCH_EMOTION', 'MEDIUM', 380, '2026-08-09 16:39:38'),
  (991, 172, 991, 'user', '家里经济压力大，我不敢跟他们说我在学校也很吃力', NULL, NULL, 0, '2026-08-09 16:53:13'),
  (992, 172, 992, 'assistant', '被反复比较是很难受的，尤其是来自最亲近的人。

和父母的沟通可以降低目标：不追求说服他们，只求把话说完。比如「我知道你们是为我好，但我想先按自己的想法试一年」。

有没有哪个家里人是你觉得相对能说上话的？', 'PSYCH_EMOTION', 'LOW', 402, '2026-08-09 16:53:22'),
  (993, 172, 993, 'user', '躺下之后脑子就开始不停地想事情，越想越清醒，特别痛苦', NULL, NULL, 0, '2026-08-09 18:15:13'),
  (994, 172, 994, 'assistant', '睡眠不好会连着影响情绪和注意力，你能注意到这件事本身很重要。

