先试三晚，有任何变化都可以回来跟我说。', 'PSYCH_EMOTION', 'LOW', 295, '2026-08-09 18:15:25'),
  (995, 173, 995, 'user', '感觉自己在这段关系里一直在退让，越来越不像自己了', NULL, NULL, 0, '2026-07-02 11:22:13'),
  (996, 173, 996, 'assistant', '你说「越来越不像自己」，这句话很值得停一下 —— 能意识到这点说明你其实看得很清楚。

