如果影响到了吃饭睡觉，我们再把节奏调一调。', 'PSYCH_EMOTION', 'LOW', 238, '2026-07-02 11:22:26'),
  (997, 173, 997, 'user', '爸妈总是拿我跟表姐比，每次打电话都要吵，现在都不敢接电话了', NULL, NULL, 0, '2026-07-02 12:05:13'),
  (998, 173, 998, 'assistant', '「懂事」这个词有时候是负担，你已经背了很久了。

