ALTER TABLE `user` AUTO_INCREMENT = 55;
ALTER TABLE `risk_alert` AUTO_INCREMENT = 184;
ALTER TABLE `consult_report` AUTO_INCREMENT = 77;
ALTER TABLE `conversation` AUTO_INCREMENT = 178;
ALTER TABLE `message` AUTO_INCREMENT = 1018;
ALTER TABLE `assessment_record` AUTO_INCREMENT = 65;

SELECT
  (SELECT COUNT(*) FROM `user`)               AS users,
  (SELECT COUNT(*) FROM `conversation`)       AS conversations,
  (SELECT COUNT(*) FROM `message`)            AS messages,
  (SELECT COUNT(*) FROM `risk_alert`)         AS alerts,
  (SELECT COUNT(*) FROM `assessment_record`)  AS assessments,
  (SELECT COUNT(*) FROM `consult_report`)     AS reports;
